    pass

class ReplicaNode:
    def __init__(self, node_id, is_online=True):
        self.node_id = node_id
        self.is_online = is_online
        self.log = []

    def append_entry(self, entry):
        """Append an entry to the replica's log if it is online.

        Returns:
            bool: True if the entry was appended, False otherwise.
        """
        if self.is_online:
            self.log.append(entry)
            return True
        return False

    def rollback_entry(self, entry):
        """Remove the most recent entry if it matches the provided one.
        Used when a proposal fails to reach quorum.
        """
        if self.log and self.log[-1] == entry:
            self.log.pop()

class QuorumReplicatedStateMachine:
    def __init__(self, replicas):
        # Validate replicas list
        if not isinstance(replicas, (list, tuple)):
            raise ValueError("replicas must be a list or tuple of ReplicaNode instances")
        for r in replicas:
            if not isinstance(r, ReplicaNode):
                raise ValueError("All items in replicas must be ReplicaNode instances")
        self.replicas = list(replicas)  # list of ReplicaNode
        self.quorum_size = (len(self.replicas) // 2) + 1
        self.commit_index = 0
        self.state = {}
        self.log = []  # list of all proposed entries (committed or not)

    def _validate_key(self, key):
        if not isinstance(key, str) or isinstance(key, bool):
            raise ValueError("key must be a non‑boolean string")
        if key == "":
            raise ValueError("key cannot be empty")

    def get(self, key):
        """Retrieve the committed value for *key*.

        Returns ``None`` if the key is not present.
        """
        self._validate_key(key)
        return self.state.get(key)

    def propose(self, key, value):
        """Propose a state change.

        The change is only applied to the state machine after a quorum of replicas
        have successfully appended the entry. If the quorum is not reached, the
        operation is rolled back on all replicas that accepted the entry.

        Args:
            key (str): The state key to modify.
            value: The new value associated with *key*.

        Returns:
            bool: ``True`` if the proposal was committed, ``False`` otherwise.
        """
        # Strict type validation – reject booleans where a string is expected
        self._validate_key(key)
        # No strict type enforcement for value; allow any non‑boolean if needed
        if isinstance(value, bool):
            raise ValueError("boolean values are not allowed for state entries")

        entry_idx = len(self.log) + 1
        entry = {"index": entry_idx, "key": key, "value": value}
        self.log.append(entry)

        acks = 0
        successful_replicas = []
        for replica in self.replicas:
            if replica.append_entry(entry):
                acks += 1
                successful_replicas.append(replica)

        if acks < self.quorum_size:
            # Rollback on replicas that accepted the entry
            for replica in successful_replicas:
                replica.rollback_entry(entry)
            # Also remove the entry from the local log to keep it consistent
            if self.log and self.log[-1] == entry:
                self.log.pop()
            return False

        # Quorum reached – commit the entry atomically
        self.state[key] = value
        self.commit_index = entry_idx
        return True

